        let slot = ShadowLatestSlot::new();
        assert_eq!(slot.try_submit(1_u64), ShadowSubmit::Accepted);
        assert_eq!(slot.try_submit(2_u64), ShadowSubmit::ReplacedOldUnobserved);
        assert_eq!(slot.try_take(), Some(2));
