    #[cfg(feature = "edge-measurement")]
    edge_test!(oob_audit_snapshot_exact_field_mutation_cover, {
        let root = edge_writer_root("oob-audit-cover");
        let sink = EdgeOobFailureSinkV1::open(&root, Some(7)).expect("OOB sink");
        let snapshot = sink.audit_snapshot().expect("OOB audit");

        macro_rules! assert_oob_mutation {
            ($label:literal, $mutation:expr) => {{
                let mut changed = snapshot.clone();
                $mutation(&mut changed);
                assert_ne!(changed, snapshot, "{} escaped OOB audit equality", $label);
            }};
        }
        assert_eq!(EdgeOobFailureSinkAuditSnapshotV1::COVERED_FIELD_COUNT, 5);
        assert_eq!(EdgeOobFailureSinkAuditSnapshotV1::FILE_METADATA_FIELD_COUNT, 11);
        assert_oob_mutation!(
            "writer_instance_id",
            |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
                value.writer_instance_id.push('x');
            }
        );
        assert_oob_mutation!("producer_epoch", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.producer_epoch = Some(8);
        });
        assert_oob_mutation!("next_ordinal", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.next_ordinal ^= 1;
        });
        assert_oob_mutation!("file_bytes", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_bytes.push(0);
        });
        assert_oob_mutation!("metadata.len", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_metadata.len ^= 1;
        });
        assert_oob_mutation!("metadata.mode", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_metadata.mode ^= 1;
        });
        assert_oob_mutation!("metadata.uid", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_metadata.uid ^= 1;
        });
        assert_oob_mutation!("metadata.gid", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_metadata.gid ^= 1;
        });
        assert_oob_mutation!("metadata.device", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_metadata.device ^= 1;
        });
        assert_oob_mutation!("metadata.inode", |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
            value.file_metadata.inode ^= 1;
        });
        assert_oob_mutation!(
            "metadata.hard_links",
            |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
                value.file_metadata.hard_links ^= 1;
            }
        );
        assert_oob_mutation!(
            "metadata.modified_seconds",
            |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
                value.file_metadata.modified_seconds ^= 1;
            }
        );
        assert_oob_mutation!(
            "metadata.modified_nanoseconds",
            |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
                value.file_metadata.modified_nanoseconds ^= 1;
            }
        );
        assert_oob_mutation!(
            "metadata.changed_seconds",
            |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
                value.file_metadata.changed_seconds ^= 1;
            }
        );
        assert_oob_mutation!(
            "metadata.changed_nanoseconds",
            |value: &mut EdgeOobFailureSinkAuditSnapshotV1| {
                value.file_metadata.changed_nanoseconds ^= 1;
            }
        );
        drop(sink);
        fs::remove_dir_all(root).expect("OOB audit root cleanup");
    });
    #[cfg(feature = "edge-measurement")]
    edge_test!(oob_failure_sink_open_at_survives_atomic_role_path_swap, {
        let base = edge_writer_root("oob-three-root");
        let roots = [base.join("control"), base.join("source"), base.join("consumer")];
        for root in &roots {
            fs::create_dir(root).expect("OOB role root");
            fs::set_permissions(root, fs::Permissions::from_mode(0o700))
                .expect("private OOB role root");
        }
        let source_handle = File::open(&roots[1]).expect("epoch-source directory handle");
        let source_identity = {
            let metadata = source_handle.metadata().expect("epoch-source metadata");
            (metadata.dev(), metadata.ino())
        };
        let control_identity = {
            let metadata = fs::metadata(&roots[0]).expect("campaign-control metadata");
            (metadata.dev(), metadata.ino())
        };
        assert_ne!(source_identity, control_identity);

        let control = CString::new(roots[0].as_os_str().as_bytes()).expect("control path");
        let source = CString::new(roots[1].as_os_str().as_bytes()).expect("source path");
        // SAFETY: both C strings remain alive for the call and name existing directories; the
        // exchange is atomic, so the pinned source handle remains valid throughout.
        assert_eq!(unsafe { renameat2(-100, control.as_ptr(), -100, source.as_ptr(), 2) }, 0);
        assert_eq!(
            {
                let metadata = fs::metadata(&roots[0]).expect("source inode after exchange");
                (metadata.dev(), metadata.ino())
            },
            source_identity
        );
        assert_eq!(
            {
                let metadata = fs::metadata(&roots[1]).expect("control inode after exchange");
                (metadata.dev(), metadata.ino())
            },
            control_identity
        );

        let sink = EdgeOobFailureSinkV1::open_at(&source_handle, Some(9))
            .expect("pinned source-root sink");
        sink.record("writer", "DataLedgerWriteFailed", None).expect("source-root record");
        let audit = sink.audit_snapshot().expect("source-root OOB audit");
        let original_source_oob = roots[0].join("edge-writer-failures-v1.ndjson");
        let original_control_oob = roots[1].join("edge-writer-failures-v1.ndjson");
        let oob_metadata =
            fs::metadata(&original_source_oob).expect("OOB under original source inode");
        assert_eq!(
            (audit.file_metadata.device, audit.file_metadata.inode),
            (oob_metadata.dev(), oob_metadata.ino())
        );
        assert!(!original_control_oob.exists(), "OOB bytes must never enter control inode");
        assert_eq!(
            fs::read(&original_source_oob).expect("pinned source OOB bytes"),
            audit.file_bytes
        );

        let source_alias = base.join("source-alias");
        std::os::unix::fs::symlink(&roots[0], &source_alias).expect("source sibling symlink");
        assert!(EdgeOobFailureSinkV1::open(&source_alias, Some(9)).is_err());
        fs::remove_file(source_alias).expect("source sibling symlink cleanup");
        drop(sink);
        fs::remove_dir_all(base).expect("OOB three-root cleanup");
    });

